customMethods.script:
	system.perspective.print('deleteChkShtHistoryVersion() called')

	chkShtInfo = self.view.custom.table.selection.data[0]
	self.view.custom.info = {"showBar": True, "text": "Deleting %s"%chkShtInfo['chkShtName'], "type": "INFO"}	
	retVal = system.kanoa.quality.sheet.deleteSheetWithHistory(chkShtInfo['chkShtId'], self.view.custom.security.userId)
	if retVal > 0: system.perspective.sendMessage('showSuccessfulToast', {'message': '%s deleted'%chkShtInfo['chkShtName']})
	else: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to delete %s'%chkShtInfo['chkShtName']})

	self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}	

#	self.view.refreshBinding("custom.table.data")
	system.perspective.sendMessage('refreshChkShts', {})

	return

